// Limpia el Excel de Marisa y decide que se carga y que no (HU-10).
//
// El CSV mezcla apartados y abonos en la misma hoja: las filas con el mismo
// cliente + modelo + talla son el mismo apartado, la primera es el alta y las
// demas son abonos.
//
// No se carga: abono inicial por debajo de 5 EUR, importes o fechas ilegibles,
// o filas ya migradas. Todo eso sale en el informe de dudosos para que Marisa decida.
const filasApartados = $('Parsear CSV de apartados').all().map((i) => i.json ?? {});
const filasVentas = $('Parsear CSV de ventas').all().map((i) => i.json ?? {});

// '10,00' / '1.842,30' / '10.00' -> numero
const aNumero = (bruto) => {
  if (bruto === null || bruto === undefined) return null;
  if (typeof bruto === 'number') return Number.isFinite(bruto) ? bruto : null;
  let s = String(bruto).trim().replace(/\s/g, '').replace(/[^0-9.,]/g, '');
  if (!s) return null;
  const coma = s.lastIndexOf(',');
  const punto = s.lastIndexOf('.');
  if (coma >= 0 && punto >= 0) {
    s = coma > punto ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (coma >= 0) {
    s = s.replace(',', '.');
  } else if (punto >= 0) {
    // Solo hay punto: si el decimal tiene 3 cifras es separador de miles (1.842),
    // si no, son decimales (89.90).
    const decimales = s.length - punto - 1;
    if (decimales === 3) s = s.replace(/\./g, '');
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

// '02/09/2026' / '7/9/26' / '2026-09-02' -> 'AAAA-MM-DD'
const aFecha = (bruto) => {
  const t = String(bruto ?? '').trim();
  let m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);
  if (m) {
    let anio = Number(m[3]);
    if (anio < 100) anio += 2000;
    return anio + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0');
  }
  m = t.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})$/);
  if (m) return m[1] + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[3]).padStart(2, '0');
  return null;
};

const nombrePropio = (s) => String(s ?? '').trim().toLowerCase()
  .split(/\s+/).filter(Boolean)
  .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
  .join(' ');

const telefono = (s) => {
  const digitos = String(s ?? '').replace(/[^0-9]/g, '');
  if (digitos.length === 9) return digitos.slice(0, 3) + ' ' + digitos.slice(3, 6) + ' ' + digitos.slice(6);
  return String(s ?? '').trim();
};

// Lo que ya hay en la app: si el apartado esta creado (mismo cliente, producto y
// fecha) no se vuelve a crear, asi el flujo se puede ejecutar dos veces.
const existentes = $('Buscar apartados existentes').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((a) => a && a.cliente);
const claveDe = (cliente, producto, fecha) =>
  [nombrePropio(cliente), String(producto ?? '').trim(), String(fecha ?? '')].join('|');
const yaMigrados = new Set(existentes.map((a) => claveDe(a.cliente, a.producto, a.fecha)));

const ABONO_MINIMO = 5;
const dudosos = [];

// Agrupar por cliente + modelo + talla.
const grupos = new Map();
for (const fila of filasApartados) {
  const cliente = nombrePropio(fila.cliente);
  const modelo = String(fila.modelo ?? '').trim();
  const talla = String(fila.talla ?? '').trim();
  const clave = [cliente, modelo, talla].join('|');
  if (!grupos.has(clave)) grupos.set(clave, []);
  grupos.get(clave).push(fila);
}

const aCrear = [];
for (const [clave, filas] of grupos) {
  const alta = filas[0];
  const resto = filas.slice(1);
  const cliente = nombrePropio(alta.cliente);
  const producto = String(alta.modelo ?? '').trim();
  const talla = String(alta.talla ?? '').trim();
  const precio = aNumero(alta.precio);
  const abonoInicial = aNumero(alta.abono);
  const fecha = aFecha(alta.fecha);
  const claveMigracion = claveDe(cliente, producto, fecha);

  if (!cliente || !producto) {
    dudosos.push({ fecha: alta.fecha, cliente, producto, importe: alta.abono, motivo: 'falta cliente o modelo' });
    continue;
  }
  if (yaMigrados.has(claveMigracion)) continue;
  if (precio === null || precio <= 0) {
    dudosos.push({ fecha: alta.fecha, cliente, producto, importe: alta.precio, motivo: 'precio ilegible' });
    continue;
  }
  if (!fecha) {
    dudosos.push({ fecha: alta.fecha, cliente, producto, importe: alta.precio, motivo: 'fecha ilegible' });
    continue;
  }
  if (abonoInicial === null || abonoInicial < ABONO_MINIMO) {
    dudosos.push({
      fecha: alta.fecha, cliente, producto, importe: alta.abono,
      motivo: 'abono inicial por debajo de ' + ABONO_MINIMO + ' EUR',
    });
    // Los abonos posteriores de este apartado tampoco se pueden cargar.
    for (const fila of resto) {
      dudosos.push({
        fecha: fila.fecha, cliente, producto, importe: fila.abono,
        motivo: 'el apartado no se ha cargado (abono inicial bajo el minimo)',
      });
    }
    continue;
  }
  if (abonoInicial > precio) {
    dudosos.push({ fecha: alta.fecha, cliente, producto, importe: alta.abono, motivo: 'el abono supera el precio' });
    continue;
  }

  // Abonos posteriores: cada fila con la misma clave es un abono más.
  const abonos = [];
  let acumulado = abonoInicial;
  for (const fila of resto) {
    const importe = aNumero(fila.abono);
    const fechaAbono = aFecha(fila.fecha);
    if (importe === null || importe <= 0) {
      dudosos.push({ fecha: fila.fecha, cliente, producto, importe: fila.abono, motivo: 'importe de abono ilegible' });
      continue;
    }
    if (!fechaAbono) {
      dudosos.push({ fecha: fila.fecha, cliente, producto, importe: fila.abono, motivo: 'fecha de abono ilegible' });
      continue;
    }
    if (acumulado + importe > precio + 0.001) {
      dudosos.push({ fecha: fila.fecha, cliente, producto, importe: fila.abono, motivo: 'el abono supera lo pendiente' });
      continue;
    }
    acumulado += importe;
    abonos.push({ importe, fecha: fechaAbono });
  }

  aCrear.push({
    json: {
      tipo: 'apartado',
      clave: claveMigracion,
      apartado: {
        cliente,
        telefono: telefono(alta.telefono),
        producto,
        talla,
        precio,
        abono_inicial: abonoInicial,
        forma_pago: 'efectivo',
        fecha,
      },
      abonos,
    },
  });
}

// Las ventas del CSV: se ignoran las filas de totales (p. ej. 'TOTAL SEPTIEMBRE (a mano)').
for (const fila of filasVentas) {
  const concepto = String(fila.concepto ?? '').trim();
  const importe = aNumero(fila.importe);
  const fecha = aFecha(fila.fecha);
  if (!concepto) continue;
  if (/total/i.test(concepto)) continue;
  if (importe === null) {
    dudosos.push({ fecha: fila.fecha, cliente: '-', producto: concepto, importe: fila.importe, motivo: 'importe de venta ilegible' });
    continue;
  }
  if (!fecha) {
    dudosos.push({ fecha: fila.fecha, cliente: '-', producto: concepto, importe: fila.importe, motivo: 'fecha de venta ilegible' });
  }
}

const salida = aCrear;
salida.push({ json: { tipo: 'dudosos', lista: dudosos, total: dudosos.length, apartados_a_crear: aCrear.length } });
return salida;

// Comprueba la creacion de cada apartado y deja su id para sus abonos.
// El nodo HTTP devuelve un item por apartado creado: aqui se mira cada uno.
const claveDe = (cliente, producto, fecha) =>
  [String(cliente ?? '').trim().toLowerCase(), String(producto ?? '').trim(), String(fecha ?? '')].join('|');

const originales = $('Limpiar y decidir').all().map((i) => i.json).filter((j) => j.tipo === 'apartado');
const salida = [];

for (const item of $input.all()) {
  const creado = item.json ?? {};
  const original = originales.find((j) => claveDe(j.apartado.cliente, j.apartado.producto, j.apartado.fecha)
    === claveDe(creado.cliente, creado.producto, creado.fecha)) ?? {};

  if (creado.id === undefined) {
    salida.push({
      json: {
        ok: false,
        clave: original.clave ?? null,
        detalle: String(creado.detail ?? creado.message ?? 'La API no ha creado el apartado'),
        abonos: [],
      },
    });
    continue;
  }

  salida.push({
    json: {
      ok: true,
      clave: original.clave ?? null,
      apartado_id: creado.id,
      cliente: creado.cliente,
      producto: creado.producto,
      detalle: 'Apartado #' + creado.id + ' creado con fecha ' + creado.fecha,
      abonos: original.abonos ?? [],
    },
  });
}

return salida;

// Reparte los abonos de cada apartado en un item por abono.
const salida = [];
for (const item of $input.all()) {
  const creado = item.json ?? {};
  if (!creado.ok) continue;
  for (const abono of (creado.abonos ?? [])) {
    salida.push({ json: { apartado_id: creado.apartado_id, cliente: creado.cliente, abono } });
  }
}
return salida;

// Informe de dudosos: lo que NO se ha cargado, para que Marisa decida (HU-10).
const decision = $('Limpiar y decidir').all().map((i) => i.json).find((j) => j.tipo === 'dudosos') ?? { lista: [], total: 0, apartados_a_crear: 0 };
const comprobar = $('Comprobar la creaci\u00f3n');
const creados = comprobar.isExecuted ? comprobar.all().map((i) => i.json).filter((j) => j.ok) : [];
const fallos = comprobar.isExecuted ? comprobar.all().map((i) => i.json).filter((j) => !j.ok) : [];

const emailTienda = $vars.EMAIL_MARISA || 'marisa@pasofirme.example';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lineas = (decision.lista ?? []).map((d) => '  - ' + d.fecha + ' | ' + d.cliente + ' | ' + d.producto + ' | ' + d.importe + ' | ' + d.motivo);

const cuerpo = [
  'Migracion del Excel antiguo:',
  '',
  'Apartados cargados: ' + creados.length,
  'Filas pendientes de crear: ' + (decision.apartados_a_crear ?? 0),
  'Filas que NO se han cargado: ' + (decision.total ?? 0),
  '',
  'Lo que no se ha cargado (decide tu que hacer con esto):',
].concat(lineas.length ? lineas : ['  (ninguno)']).concat([
  '',
  fallos.length ? 'Errores de la API: ' + fallos.map((f) => f.detalle).join('; ') : '',
]).join('\n');

const tabla = '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Fecha</th><th>Cliente</th><th>Producto</th><th>Importe</th><th>Motivo</th></tr>'
  + (decision.lista ?? []).map((d) => '<tr><td>' + escapar(d.fecha) + '</td><td>' + escapar(d.cliente) + '</td><td>' + escapar(d.producto) + '</td><td>' + escapar(d.importe) + '</td><td>' + escapar(d.motivo) + '</td></tr>').join('')
  + '</table>';

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Migracion del Excel · ' + (decision.total ?? 0) + ' filas sin cargar',
    cuerpo,
    cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>' + tabla,
  },
}];
